package com.bhashasetu.service;
import com.bhashasetu.config.BhashaSetuProperties; import com.bhashasetu.model.*; import com.bhashasetu.repository.SchemeRepository; import java.io.*; import java.nio.charset.StandardCharsets; import java.nio.file.*; import java.security.*; import java.time.*; import java.util.*; import org.apache.commons.csv.*; import org.springframework.boot.*; import org.springframework.stereotype.Component; import org.springframework.transaction.annotation.Transactional;
/** Explicit, idempotent importer for the curated CSV files. It never changes rules on a conflicting existing source key unless IMPORT_OVERWRITE is true. */
@Component public class DatasetImporter implements ApplicationRunner { private final SchemeRepository repo; private final BhashaSetuProperties props; public DatasetImporter(SchemeRepository r,BhashaSetuProperties p){repo=r;props=p;} public void run(ApplicationArguments args)throws Exception{if(props.isImportOnStartup())importDirectory(Path.of(props.getDatasetDirectory()),props.isImportOverwrite());}
 @Transactional public ImportReport importDirectory(Path dir,boolean overwrite)throws IOException {int created=0,unchanged=0,conflicts=0;for(String prefix:List.of("central","state")){Map<String,List<CSVRecord>> rules=rules(dir.resolve(prefix+"_eligibility_rules.csv"));try(Reader in=reader(dir.resolve(prefix+"_schemes_master.csv"));CSVParser csv=CSVFormat.DEFAULT.builder().setHeader().setSkipHeaderRecord(true).build().parse(in)){for(CSVRecord row:csv){String name=row.get("scheme_name").trim(),state=row.get("state_or_ut").trim();String key=curatedSourceKey(prefix,state,name);Optional<Scheme> old=repo.findBySourceKey(key);if(old.isPresent()&&!overwrite){unchanged++;continue;} Scheme s=old.orElseGet(Scheme::new); if(old.isPresent())s.getRules().clear();fill(s,row,key);for(CSVRecord rr:rules.getOrDefault(name,List.of())){EligibilityRule r=new EligibilityRule();r.setScheme(s);r.setField(rr.get("field"));r.setOperator(operator(rr.get("operator")));r.setValue(value(rr.get("value")));r.setValueType(has(rr,"value_type")?rr.get("value_type"):"string");s.getRules().add(r);}repo.save(s);if(old.isPresent())conflicts++;else created++;}}}return new ImportReport(created,unchanged,conflicts);}
 private Map<String,List<CSVRecord>> rules(Path p)throws IOException{Map<String,List<CSVRecord>>out=new HashMap<>();try(Reader in=reader(p);CSVParser csv=CSVFormat.DEFAULT.builder().setHeader().setSkipHeaderRecord(true).build().parse(in)){for(CSVRecord r:csv)out.computeIfAbsent(r.get("scheme_name").trim(),x->new ArrayList<>()).add(r);}return out;} private Reader reader(Path path)throws IOException{BufferedReader in=Files.newBufferedReader(path,StandardCharsets.UTF_8);in.mark(1);if(in.read()!=0xFEFF)in.reset();return in;} private boolean has(CSVRecord r,String h){return r.isMapped(h)&&!r.get(h).isBlank();} private String operator(String o){return switch(o.trim().toLowerCase(Locale.ROOT)){case "equals"->"==";case "not_equals"->"!=";case "greater_than"->">";case "greater_than_or_equal"->">=";case "less_than"->"<";case "less_than_or_equal"->"<=";default->o;};}private Object value(String x){String v=x.trim();if(v.equalsIgnoreCase("true")||v.equalsIgnoreCase("false"))return Boolean.valueOf(v);if(v.matches("-?\\d+(\\.\\d+)?"))return new java.math.BigDecimal(v);if(v.contains("|"))return Arrays.stream(v.split("\\|")).map(String::trim).toList();return v;}static String curatedSourceKey(String group,String state,String name){return "curated:"+sha(pythonIdentity(group,state,name));} private static String pythonIdentity(String group,String state,String name){return "["+json(group.toUpperCase(Locale.ROOT))+", "+json(group.equals("state")?state.trim().toLowerCase(Locale.ROOT):"")+", "+json(name.trim().toLowerCase(Locale.ROOT))+"]";} private static String json(String s){return "\""+s.replace("\\","\\\\").replace("\"","\\\"").replace("\n","\\n").replace("\r","\\r").replace("\t","\\t")+"\"";}private static String sha(String x){try{byte[] d=MessageDigest.getInstance("SHA-256").digest(x.getBytes(StandardCharsets.UTF_8));return HexFormat.of().formatHex(d);}catch(NoSuchAlgorithmException e){throw new IllegalStateException(e);}}
 private void fill(Scheme s,CSVRecord r,String key){s.setSourceKey(key);s.setName(r.get("scheme_name"));s.setGovernmentLevel(r.get("government_level"));s.setState(r.get("state_or_ut"));s.setMinistryOrDepartment(r.get("ministry_or_department"));s.setCategory(r.get("category"));s.setRawCategory(r.get("category"));s.setDescription(r.get("short_description"));s.setStatusConfidence(r.get("status_confidence"));s.setOfficialUrl(r.get("official_source_url"));s.setSecondarySourceUrl(r.get("secondary_source_url"));s.setBenefitType(r.get("benefit_type"));s.setBenefitSummary(r.get("benefit_summary"));s.setBenefitAmount(r.get("benefit_amount"));s.setApplicationMethod(r.get("application_method"));s.setOfficialApplicationUrl(r.get("official_application_url"));s.setConfidenceNotes(r.get("confidence_notes"));s.setOtherEligibilityConditions(r.get("other_eligibility_conditions"));s.setActive(true);if(has(r,"last_checked_date"))try{s.setLastCheckedDate(LocalDate.parse(r.get("last_checked_date")));}catch(Exception ignored){}} public record ImportReport(int created,int unchanged,int updated){}
}
